package com.lifeos.tasks; import com.lifeos.tasks.dto.*; import com.lifeos.users.*; import com.lifeos.shared.exception.*; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.*;
@Service public class TaskService { private final TaskRepository repo; private final UserRepository users; public TaskService(TaskRepository repo,UserRepository users){this.repo=repo;this.users=users;} private User user(String email){return users.findByEmail(email).orElseThrow(()->new ResourceNotFoundException("User not found"));} private Task owned(Long id,String email){return repo.findByIdAndUserId(id,user(email).getId()).orElseThrow(()->new ResourceNotFoundException("Task not found"));} public List<TaskResponse> list(String email){return repo.findAllByUserIdOrderByCreatedAtDesc(user(email).getId()).stream().map(TaskResponse::from).toList();} public TaskResponse get(Long id,String email){return TaskResponse.from(owned(id,email));} public TaskResponse create(TaskRequest r,String email){Task t=new Task();t.setUser(user(email));apply(t,r);return TaskResponse.from(repo.save(t));} public TaskResponse update(Long id,TaskRequest r,String email){Task t=owned(id,email);apply(t,r);return TaskResponse.from(repo.save(t));} public void delete(Long id,String email){repo.delete(owned(id,email));} private void apply(Task t,TaskRequest r){t.setTitle(r.title().trim());t.setDescription(r.description());t.setStatus(r.status());t.setPriority(r.priority());t.setEstimatedMinutes(r.estimatedMinutes());t.setDueDate(r.dueDate());t.setCompletedAt(r.status()==TaskStatus.COMPLETED?(t.getCompletedAt()==null?LocalDateTime.now():t.getCompletedAt()):null);}}
